<script setup lang="ts">
import {computed,ref} from 'vue';
import type {ProjectPresentation} from './content-types';
import {categoryLabel,projectDescription,projectDate,projectImage} from './content-labels';
import ProjectImage from './ProjectImage.vue';
import {getBridge} from '../lib/bridge';
const props=defineProps<{title:string;summary?:string|null;source:string;author?:string|null;downloads?:number|null;presentation?:ProjectPresentation}>();
defineEmits<{close:[]}>();
const data=computed(()=>props.presentation),html=computed(()=>projectDescription(data.value?.description||props.summary||'来源未提供完整简介。'));
const failed=ref(new Set<string>()),gallery=computed(()=>(data.value?.gallery??[]).map(projectImage).filter(u=>u&&!failed.value.has(u)));
const linkLabels:Record<string,string>={wiki_url:'项目 Wiki',source_url:'源代码',issues_url:'问题反馈',discord_url:'Discord',websiteUrl:'项目网站',wikiUrl:'项目 Wiki',issuesUrl:'问题反馈',sourceUrl:'源代码'};
function open(url:string){try{const u=new URL(url);if(u.protocol==='https:'&&!u.username&&!u.password)void getBridge().openExternal(u.href);}catch{/* 非法展示链接不执行 */}}
function imageFailed(url:string){failed.value=new Set([...failed.value,url]);}
</script>
<template><section class="content-detail" data-project-introduction><div class="launcher-glass content-detail-header"><ProjectImage :url="data?.iconUrl" :title="title"/><div><span class="launcher-overline">{{source}}</span><h2>{{title}}</h2><p>{{summary||'来源未提供简短简介'}}</p><small v-if="author||downloads!=null">{{author||'作者未提供'}}<template v-if="downloads!=null"> · {{downloads.toLocaleString()}} 次下载</template></small><div class="content-tags"><span v-for="tag in data?.categories" :key="tag.id">{{categoryLabel(tag.id,tag.name)}}</span></div></div><button class="launcher-text-button" data-close-project @click="$emit('close')">返回列表</button></div><div class="content-detail-grid"><article class="launcher-glass content-description"><h3>项目简介</h3><div v-if="gallery.length" class="content-gallery" data-project-gallery><img v-for="url in gallery.slice(0,12)" :key="url" :src="url" :alt="title+' 项目展示'" loading="lazy" decoding="async" referrerpolicy="no-referrer" @error="imageFailed(url)"/></div><div class="content-markdown" v-html="html"></div><p v-if="failed.size" class="launcher-caption">部分项目图片暂时无法显示。</p></article><aside class="launcher-glass content-compatibility"><h3>兼容性</h3><p>Minecraft：Java 版</p><div class="content-tags"><span v-for="v in data?.gameVersions?.slice(-24).reverse()" :key="v">{{v}}</span></div><p v-if="!data?.gameVersions?.length" class="launcher-caption">游戏版本以文件详情为准</p><p v-if="(data?.gameVersions?.length??0)>24" class="launcher-caption">显示最近列出的24个标签，完整兼容性以所选文件为准。</p><div class="content-tags"><span v-for="v in data?.loaders" :key="v">{{v}}</span></div><p v-if="data?.clientSide">客户端：{{({required:'必需',optional:'可选',unsupported:'不支持',unknown:'未说明'} as Record<string,string>)[data.clientSide]??'未说明'}}</p><p v-if="data?.serverSide">服务端：{{({required:'必需',optional:'可选',unsupported:'不支持',unknown:'未说明'} as Record<string,string>)[data.serverSide]??'未说明'}}</p><h3>项目信息</h3><p>发布：{{projectDate(data?.publishedAt)}}</p><p>更新：{{projectDate(data?.updatedAt)}}</p><template v-if="Object.keys(data?.links??{}).length"><h3>相关链接</h3><button v-for="(url,key) in data?.links" :key="key" class="launcher-text-button content-link" @click="open(url)">{{linkLabels[key]??'项目链接'}} ↗</button></template></aside></div></section></template>
<style scoped>
.content-detail{margin:24px 0}.content-detail-header{display:flex;gap:22px;align-items:start;padding:24px}.content-detail-header>div{flex:1;min-width:0}.content-detail-header h2{font-size:26px;margin:7px 0}.content-detail-header p{margin:8px 0;line-height:1.7;color:var(--launcher-muted);overflow-wrap:anywhere}.content-detail-header small{color:var(--launcher-muted)}.content-tags{display:flex;gap:7px;flex-wrap:wrap;margin-top:12px}.content-tags span{font-size:12px;border-radius:8px;background:var(--launcher-line);padding:5px 9px;overflow-wrap:anywhere}.content-detail-grid{display:grid;grid-template-columns:minmax(0,1fr) 250px;gap:20px;margin-top:20px}.content-description,.content-compatibility{padding:24px;min-width:0;align-self:start}.content-description h3,.content-compatibility h3{margin:0 0 16px;font-size:18px}.content-compatibility h3:not(:first-child){margin-top:28px}.content-compatibility p{color:var(--launcher-muted);font-size:13px;line-height:1.7}.content-gallery{display:grid;gap:16px;margin-bottom:24px}.content-gallery img{display:block;width:100%;height:auto;max-height:500px;object-fit:contain;border-radius:14px}.content-markdown{line-height:1.75;overflow-wrap:anywhere;font-size:14px}.content-markdown :deep(pre){overflow:auto;padding:12px;background:var(--launcher-line);border-radius:10px}.content-markdown :deep(table){display:block;overflow:auto}.content-markdown :deep(h1),.content-markdown :deep(h2){font-size:22px;line-height:1.3}.content-markdown :deep(blockquote){margin:16px 0;padding-left:18px;border-left:2px solid var(--launcher-gold)}.content-link{display:block;margin:12px 0}
@media(max-width:1000px){.content-detail-grid{grid-template-columns:minmax(0,1fr)}.content-detail-header{flex-wrap:wrap;padding:18px;gap:14px}.content-detail-header>div{flex-basis:calc(100% - 100px)}.content-detail-header h2{font-size:21px}.content-description,.content-compatibility{padding:18px}}
</style>
